### Step 1: Prometheus Metrics Fetcher

```go
type MetricsFetcher struct {
    client api_v1.API
}

func (m *MetricsFetcher) FetchNodeUtilization(ctx context.Context, 
    nodeSelector string, duration time.Duration) ([]MetricPoint, error) {

    query := fmt.Sprintf(`
        avg by (instance) (
            rate(node_cpu_seconds_total{mode!="idle", instance=~"%s"}[5m])
        ) * 100
    `, nodeSelector)

    result, _, err := m.client.QueryRange(ctx, query, v1.Range{
        Start: time.Now().Add(-duration),
        End:   time.Now(),
        Step:  time.Minute,
    })

    // Parse into time series
    var points []MetricPoint
    for _, series := range result.(model.Matrix) {
        for _, sample := range series.Values {
            points = append(points, MetricPoint{
                Timestamp: sample.Timestamp.Time(),
                Value:     float64(sample.Value),
            })
        }
    }
    return points, nil
}

// Also fetch pod-level metrics for more granular predictions
