### Step 3: Feature Engineering

```go
type FeatureEngine struct{}

func (f *FeatureEngine) ExtractFeatures(raw []MetricPoint) []FeatureVector {
    var features []FeatureVector

    // Group by hour-of-day, day-of-week
    for _, p := range raw {
        fv := FeatureVector{
            Timestamp:     p.Timestamp,
            Value:         p.Value,
            HourOfDay:     p.Timestamp.Hour(),
            DayOfWeek:     int(p.Timestamp.Weekday()),
            IsWeekend:     p.Timestamp.Weekday() >= time.Saturday,
            IsBusinessHour: p.Timestamp.Hour() >= 9 && p.Timestamp.Hour() < 17,
            RollingAvg15m: 0, // computed below
            RollingAvg1h:  0,
        }
        features = append(features, fv)
    }

    // Compute rolling windows
    for i := range features {
        if i >= 15 {
            sum := 0.0
            for j := i - 15; j < i; j++ {
                sum += features[j].Value
            }
            features[i].RollingAvg15m = sum / 15
        }
        if i >= 60 {
            sum := 0.0
            for j := i - 60; j < i; j++ {
                sum += features[j].Value
            }
            features[i].RollingAvg1h = sum / 60
        }
    }

    return features
}
```

### Step 4: Complete Forecast Engine

```go
type ForecastEngine struct {
    metricsFetcher *MetricsFetcher
    prophetClient  *ProphetServiceClient
    modelCache     map[string]*ModelState // per node group
}

type ModelState struct {
    LastTraining time.Time
    ModelVersion string
    Accuracy     float64 // MAPE from last validation
}

func (e *ForecastEngine) Predict(ctx context.Context, 
    nodeGroup string, horizon time.Duration) (*ForecastResult, error) {

    // 1. Fetch 7 days of history
    history, err := e.metricsFetcher.FetchNodeUtilization(ctx, nodeGroup, 7*24*time.Hour)
    if err != nil {
        return nil, fmt.Errorf("fetch metrics: %w", err)
    }

    // 2. Check if model needs retraining (every 24h or on accuracy degradation)
    state, exists := e.modelCache[nodeGroup]
    if !exists || time.Since(state.LastTraining) > 24*time.Hour || state.Accuracy < 0.7 {
        // Retrain
        if err := e.trainModel(ctx, nodeGroup, history); err != nil {
            return nil, err
        }
    }

    // 3. Run inference
    forecast, err := e.prophetClient.Predict(ctx, history, horizon)
    if err != nil {
        return nil, err
    }

    // 4. Add confidence intervals
    result := &ForecastResult{
        Points: forecast,
        Confidence: calculateConfidence(forecast),
        RecommendedNodes: forecastToNodeCount(forecast),
    }

    return result, nil
}

func (e *ForecastEngine) trainModel(ctx context.Context, 
    nodeGroup string, history []MetricPoint) error {

    // Split: 80% train, 20% validation
    split := int(float64(len(history)) * 0.8)
    trainSet := history[:split]
    valSet := history[split:]

    // Train
    if err := e.prophetClient.Train(ctx, nodeGroup, trainSet); err != nil {
        return err
    }

    // Validate
    valForecast, _ := e.prophetClient.Predict(ctx, trainSet, 
        time.Duration(len(valSet))*time.Minute)

    mape := calculateMAPE(valSet, valForecast)

    e.modelCache[nodeGroup] = &ModelState{
        LastTraining: time.Now(),
        Accuracy:     1 - mape,
    }

    return nil
}
