## 3. Handling Non-Elastic Node Groups (GPU, Spot, Reserved)

This is the hardest part. Different node types need different scaling strategies.

```go
type NodeGroupType int

const (
    NodeGroupOnDemand   NodeGroupType = iota
    NodeGroupSpot
    NodeGroupGPU
    NodeGroupReserved
    NodeGroupBareMetal
)

type NodeGroupConfig struct {
    Name              string
    Type              NodeGroupType
    MinSize           int
    MaxSize           int
    WarmupTime        time.Duration // time to become ready
    CooldownPeriod    time.Duration // min time between scale events
    SpotInterruptRate float64       // for spot: probability of interruption
    ReservedCount     int           // fixed capacity for reserved
    GPUType           string        // e.g., "A100", "V100"
    Region            string
    Zone              string
}

type NodeGroupManager struct {
    cloudClient      *autoscaling.Client
    ec2Client        *ec2.Client
    nodeGroups       map[string]*NodeGroupConfig
    pendingActions   map[string]*ScaleAction
}

func (m *NodeGroupManager) CalculateEffectiveCapacity(ctx context.Context, 
    ng *NodeGroupConfig) (int, error) {

    switch ng.Type {
    case NodeGroupOnDemand:
        return m.getASGCapacity(ctx, ng.Name)

    case NodeGroupSpot:
        // Spot: account for potential interruptions
        asgCapacity, _ := m.getASGCapacity(ctx, ng.Name)
        // Reduce by interruption probability
        effective := int(float64(asgCapacity) * (1 - ng.SpotInterruptRate))
        // Add buffer for re-provisioning time
        buffer := int(float64(asgCapacity) * 0.2) // 20% buffer
        return effective + buffer, nil

    case NodeGroupGPU:
        // GPU: long warmup, expensive, avoid flapping
        asgCapacity, _ := m.getASGCapacity(ctx, ng.Name)
        // GPU nodes take 5-15 min to warm up
        // Use predictive buffer: pre-warm based on forecast
        return asgCapacity, nil

    case NodeGroupReserved:
        // Reserved: fixed capacity, cannot scale
        return ng.ReservedCount, nil

    case NodeGroupBareMetal:
        // Bare metal: very long provisioning (hours)
        // Only scale based on long-term forecasts (days)
        return m.getCurrentCount(ctx, ng.Name)
    }
    return 0, nil
}

// Special handling for GPU node scaling
func (m *NodeGroupManager) ScaleGPUNodeGroup(ctx context.Context, 
    ng *NodeGroupConfig, desired int, forecast *ForecastResult) error {

    current, _ := m.getCurrentCount(ctx, ng.Name)

    // GPU scaling rules:
    // 1. Only scale up if forecast shows sustained demand (>30 min)
    // 2. Pre-warm 15 min before predicted spike
    // 3. Scale down slowly (cooldown: 10 min)
    // 4. Never scale down if pods are using GPU

    if desired > current {
        // Check forecast: is demand sustained?
        sustained := true
        for _, p := range forecast.Points[:30] { // next 30 min
            if p.Value < forecast.Threshold {
                sustained = false
                break
            }
        }

        if sustained {
            // Pre-warm: launch instances early
            launchTime := time.Now().Add(15 * time.Minute)
            m.schedulePreWarm(ctx, ng, desired-current, launchTime)
        }
    } else if desired < current {
        // Check GPU pod utilization
        gpuPods, _ := m.listGPUPods(ctx)
        if len(gpuPods) == 0 {
            // Safe to scale down, but do it gradually
            m.scheduleGradualScaleDown(ctx, ng, current-desired, 5*time.Minute)
        }
    }

    return nil
}

// Spot instance handling with diversification
func (m *NodeGroupManager) LaunchSpotWithFallback(ctx context.Context, 
    count int, instanceTypes []string, zones []string) error {

    // Try spot in multiple instance types and zones
    for _, instanceType := range instanceTypes {
        for _, zone := range zones {
            req := &ec2.RequestSpotInstancesInput{
                InstanceCount: aws.Int32(int32(count)),
                Type:          ec2.SpotInstanceTypePersistent,
                InstanceInterruptionBehavior: ec2.InstanceInterruptionBehaviorStop,
                LaunchSpecification: &ec2.RequestSpotLaunchSpecification{
                    InstanceType: aws.String(instanceType),
                    Placement:    &ec2.SpotPlacement{AvailabilityZone: aws.String(zone)},
                },
                ValidUntil: aws.Time(time.Now().Add(2 * time.Minute)),
            }

            resp, err := m.ec2Client.RequestSpotInstances(ctx, req)
            if err == nil {
                // Success
                m.trackSpotRequest(resp)
                return nil
            }
            // Fall through to next type/zone
        }
    }

    // Fallback: launch on-demand
    return m.LaunchOnDemand(ctx, count, instanceTypes[0], zones[0])
}
```

### Predictive Buffer Strategy for Non-Elastic Groups

```go
type PredictiveBuffer struct {
    // Maintain a "warm pool" of nodes based on forecast
    baseNodes      int  // always-on nodes
    bufferNodes    int  // pre-warmed but empty
    burstNodes     int  // spot/on-demand for spikes
}

func (p *PredictiveBuffer) CalculateBufferSize(forecast *ForecastResult, 
    ng *NodeGroupConfig) int {

    // For GPU: buffer = forecasted peak - current, with 20% safety margin
    peakForecast := forecast.MaxValue
    currentCapacity := forecast.CurrentValue

    buffer := int((peakForecast - currentCapacity) * 1.2)

    // Apply node group constraints
    if ng.Type == NodeGroupGPU {
        // GPU: smaller buffer, more reliance on forecast accuracy
        buffer = min(buffer, 4) // max 4 GPU buffer nodes
    } else if ng.Type == NodeGroupSpot {
        // Spot: larger buffer due to interruption risk
        buffer = int(float64(buffer) * 1.5)
    }

    return clamp(buffer, 0, ng.MaxSize-ng.MinSize)
}
```

