### External Scaler Implementation (gRPC)

```go
// scaler.go - implements KEDA external scaler protocol
package main

import (
    "context"
    "math"

    "google.golang.org/grpc"
    "google.golang.org/grpc/reflection"

    pb "github.com/kedacore/keda/v2/pkg/scalers/externalscaler"
)

type PredictiveScaler struct {
    pb.UnimplementedExternalScalerServer
    forecastEngine *ForecastEngine
    metricsFetcher *MetricsFetcher
}

// IsActive: KEDA calls this to check if scaling is needed
func (s *PredictiveScaler) IsActive(ctx context.Context, 
    req *pb.ScalerIsActiveRequest) (*pb.ScalerIsActiveResponse, error) {

    // Get current load
    metrics, _ := s.metricsFetcher.FetchCurrentMetrics(ctx, req.ScalerMetadata["namespace"])

    // Get forecast for next 5 minutes
    forecast, _ := s.forecastEngine.Predict(ctx, req.ScalerMetadata["deployment"], 5*time.Minute)

    // Is active if current or predicted load > threshold
    threshold, _ := strconv.ParseFloat(req.ScalerMetadata["threshold"], 64)
    isActive := metrics.CurrentValue > threshold || forecast.Next5Min > threshold

    return &pb.ScalerIsActiveResponse{Result: isActive}, nil
}

// GetMetricSpec: returns the metric that HPA will use
func (s *PredictiveScaler) GetMetricSpec(ctx context.Context,
    req *pb.ScalerGetMetricSpecRequest) (*pb.ScalerGetMetricSpecResponse, error) {

    metricName := "predictive-" + req.ScalerMetadata["deployment"]

    return &pb.ScalerGetMetricSpecResponse{
        MetricSpecs: []*pb.MetricSpec{
            {
                MetricName: metricName,
                TargetSize: 100, // target 100 "units" (interpreted by HPA)
            },
        },
    }, nil
}

// GetMetrics: returns the actual metric value (the predicted demand)
func (s *PredictiveScaler) GetMetrics(ctx context.Context,
    req *pb.ScalerGetMetricsRequest) (*pb.ScalerGetMetricsResponse, error) {

    // Get forecasted demand
    forecast, _ := s.forecastEngine.Predict(ctx, 
        req.ScalerMetadata["deployment"], 
        10*time.Minute)

    // Use the maximum predicted value in the horizon
    predictedDemand := forecast.MaxValue

    // Apply safety margin
    safetyMargin, _ := strconv.ParseFloat(req.ScalerMetadata["safety_margin"], 64)
    if safetyMargin == 0 {
        safetyMargin = 1.2 // 20% by default
    }

    metricValue := int64(math.Ceil(predictedDemand * safetyMargin))

    return &pb.ScalerGetMetricsResponse{
        MetricValues: []*pb.MetricValue{
            {
                MetricName: req.ScalerMetadata["deployment"],
                MetricValue: metricValue,
            },
        },
    }, nil
}

func main() {
    lis, _ := net.Listen("tcp", ":8080")
    s := grpc.NewServer()
    pb.RegisterExternalScalerServer(s, &PredictiveScaler{
        forecastEngine: NewForecastEngine(),
        metricsFetcher: NewMetricsFetcher(),
    })
    reflection.Register(s)
    s.Serve(lis)
}
```

