### 5.2 kubernetes/autoscaler with Custom Expanders

The Cluster Autoscaler's expander interface lets you inject custom logic:

```go
// Custom expander implementing the Expander interface
type PredictiveExpander struct {
    forecastEngine *ForecastEngine
}

func (e *PredictiveExpander) BestOption(options []Option, nodeInfo map[string]*schedulerframework.NodeInfo) *Option {
    // 1. Get forecast for each node group
    bestScore := -1.0
    var bestOption *Option

    for _, opt := range options {
        nodeGroup := opt.NodeGroup
        forecast, _ := e.forecastEngine.PredictForNodeGroup(nodeGroup.Id())

        // Score based on:
        // - How well the node type matches predicted workload
        // - Cost efficiency
        // - Warm-up time
        // - Spot interruption probability
        score := e.scoreNodeGroup(nodeGroup, forecast)

        if score > bestScore {
            bestScore = score
            bestOption = &opt
        }
    }

    return bestOption
}

