## 6. Look-Ahead Scaling via Custom Metrics API

The Custom Metrics API is the standard way to expose predicted metrics to HPA.

### Step 1: Register Custom Metrics API

```go
// Register a custom metrics API server
type PredictiveMetricsServer struct {
    forecastEngine *ForecastEngine
}

func (s *PredictiveMetricsServer) GetMetricByName(ctx context.Context, 
    name string, info custom_metrics.CustomMetricInfo) (*custom_metrics.MetricValue, error) {

    // Parse metric name: "predicted_cpu_<deployment>_<horizon_minutes>"
    parts := strings.Split(name, "_")
    deployment := parts[2]
    horizon, _ := strconv.Atoi(parts[3])

    // Get forecast
    forecast, _ := s.forecastEngine.Predict(ctx, deployment, time.Duration(horizon)*time.Minute)

    return &custom_metrics.MetricValue{
        Metric: custom_metrics.MetricIdentifier{Name: name},
        Value:  resource.NewQuantity(int64(forecast.RecommendedReplicas), resource.DecimalSI),
        Timestamp: metav1.Now(),
    }, nil
}
