### Look-Ahead Decision Algorithm

```go
type LookAheadStrategy struct {
    forecastEngine *ForecastEngine
    metricsClient  *MetricsClient
}

func (s *LookAheadStrategy) CalculateDesiredReplicas(ctx context.Context,
    deployment string, currentReplicas int32) (int32, error) {

    // Get forecasts at multiple horizons
    forecast5m, _ := s.forecastEngine.Predict(ctx, deployment, 5*time.Minute)
    forecast15m, _ := s.forecastEngine.Predict(ctx, deployment, 15*time.Minute)
    forecast30m, _ := s.forecastEngine.Predict(ctx, deployment, 30*time.Minute)

    // Get current actual load
    currentLoad, _ := s.metricsClient.GetCurrentLoad(ctx, deployment)

    // Decision logic:
    // 1. If 5m forecast > current: scale up preemptively
    // 2. If 30m forecast < current: don't scale down yet (might be a dip)
    // 3. Use the MAX of all horizons for safety

    predictedReplicas5m := forecastToReplicas(forecast5m)
    predictedReplicas15m := forecastToReplicas(forecast15m)
    predictedReplicas30m := forecastToReplicas(forecast30m)

    desired := max(predictedReplicas5m, predictedReplicas15m, predictedReplicas30m)

    // Apply hysteresis to prevent flapping
    if desired > currentReplicas {
        // Scale up immediately
        return desired, nil
    } else if desired < currentReplicas {
        // Only scale down if ALL horizons agree
        if desired < predictedReplicas5m && 
           desired < predictedReplicas15m && 
           desired < predictedReplicas30m {
            // Gradual scale down
            return max(desired, currentReplicas-1), nil
        }
    }

    return currentReplicas, nil
}
